// SUPPLIED: browser controller for the W2.10 planning comparison.
// It loads a plan (plan.json, or ?plan=A|B|C for a supplied comparison), starts one
// session from the public start, wires the labelled buttons (and arrow keys only
// when the plan includes the keyboard enhancement), renders every returned field and
// records each action with the local event helper. You do not edit this file.

import { checkReferenceApi } from "./api.js";
import { describePlan, parsePlan, proposals, type Plan } from "./plans.js";
import { evaluateShot, initialRangeState, type RangeState } from "./range.js";
import { recordEvent, type AppEvent } from "./recorder.js";
import { referenceBoard } from "./reference.js";
import type { Direction, GameState } from "./rules.js";
import { startSession, type Session } from "./session.js";

const byId = <T extends HTMLElement>(id: string): T => {
  const el = document.getElementById(id);
  if (!el) throw new Error(`missing #${id}`);
  return el as T;
};

const runId = `run-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
let sequence = 0;

function show(id: string, text: string): void {
  byId(id).textContent = text;
}

/** Render every public field of the state the rule returned. */
function renderState(state: GameState, plan: Plan): void {
  show("pos", `(${state.position.x},${state.position.y})`);
  show("moves", String(state.movesRemaining));
  show("score", String(state.score));
  show("collected", JSON.stringify(state.collected));
  show("status", state.status);
  const label = byId("item-label");
  if (plan.enhancements.includes("item-labels")) {
    label.hidden = false;
    const names = state.collected.map((id) => {
      const t = referenceBoard.treasures.find((x) => x.id === id);
      return t ? `${id} (treasure, ${t.value} points)` : id;
    });
    label.textContent = `Collected items: ${names.length ? names.join(", ") : "none yet"}`;
  } else {
    label.hidden = true;
  }
}

function renderRange(state: RangeState): void {
  show("ammo", String(state.ammunition));
  show("range-score", String(state.score));
  show("shots", String(state.shots));
  show("range-status", state.status);
}

async function record(event: Omit<AppEvent, "runId" | "sequence">): Promise<void> {
  sequence += 1;
  const full: AppEvent = { runId, sequence, ...event };
  show("recording", `Recording event ${full.sequence}…`);
  try {
    const stored = await recordEvent(full);
    show("recording", `Event ${full.sequence} recorded (collector row ${stored})`);
  } catch (error) {
    // The action already happened; only the recording failed.
    show("recording", `Recording unavailable for event ${full.sequence}: ${String(error)}`);
  }
}

async function loadPlan(): Promise<{ plan: Plan; source: string }> {
  const query = new URLSearchParams(location.search).get("plan");
  if (query !== null) {
    if (query === "A" || query === "B" || query === "C") {
      return { plan: proposals[query], source: `supplied proposal ${query} (?plan=${query}; plan.json unchanged)` };
    }
    throw new Error(`unsupported plan query "${query}" (use A, B or C, or no query for plan.json)`);
  }
  const response = await fetch("plan.json", { cache: "no-store" });
  if (!response.ok) throw new Error(`plan.json could not be loaded: HTTP ${response.status}`);
  let raw: unknown;
  try {
    raw = await response.json();
  } catch {
    throw new Error("plan.json is not valid JSON");
  }
  const checked = parsePlan(raw);
  if (!checked.ok) throw new Error(`plan.json is not a supported plan: ${checked.error}`);
  return { plan: checked.plan, source: "plan.json" };
}

function wireTreasure(session: Session): void {
  const play = (direction: Direction): void => {
    const step = session.act(direction);
    renderState(step.after, session.plan);
    const label = direction[0].toUpperCase() + direction.slice(1);
    show("result", step.accepted ? `${label} accepted` : `${label} rejected: ${step.reason}`);
    void record({
      game: "treasure",
      action: direction,
      accepted: step.accepted,
      reason: step.reason,
      before: step.before,
      after: step.after,
      plan: describePlan(session.plan),
    });
  };
  for (const button of document.querySelectorAll<HTMLButtonElement>("button[data-direction]")) {
    button.disabled = false;
    button.addEventListener("click", () => play(button.dataset.direction as Direction));
  }
  if (session.plan.enhancements.includes("keyboard")) {
    const keys: Record<string, Direction> = { ArrowUp: "north", ArrowRight: "east", ArrowDown: "south", ArrowLeft: "west" };
    document.addEventListener("keydown", (e) => {
      const direction = keys[e.key];
      if (direction) {
        e.preventDefault();
        play(direction);
      }
    });
    show("keyboard-note", "Arrow keys are enabled by this plan (the labelled buttons remain the declared input).");
  } else {
    show("keyboard-note", "Arrow keys are not part of this plan; use the labelled buttons.");
  }
}

function wireRange(plan: Plan): void {
  let state = initialRangeState();
  renderRange(state);
  for (const button of document.querySelectorAll<HTMLButtonElement>("button[data-shot]")) {
    button.disabled = false;
    button.addEventListener("click", () => {
      const type = button.dataset.shot as "hit" | "miss";
      const before = state;
      const result = evaluateShot(before, { type });
      state = result.state; // the range retains the complete returned state
      renderRange(state);
      show("range-result", result.accepted ? `${type} accepted` : `${type} rejected: ${result.reason}`);
      void record({ game: "range", action: type, accepted: result.accepted, reason: result.reason, before, after: state, plan: describePlan(plan) });
    });
  }
}

async function main(): Promise<void> {
  show("run-id", runId);
  byId<HTMLAnchorElement>("event-link").href = `events.html?run=${encodeURIComponent(runId)}`;

  // The API check runs beside local play; it does not own the game state.
  void checkReferenceApi().then((check) => {
    const el = byId("api-status");
    el.textContent = check.message;
    el.dataset.ok = String(check.ok);
  });

  let loaded: { plan: Plan; source: string };
  try {
    loaded = await loadPlan();
  } catch (error) {
    const el = byId("plan-status");
    el.textContent = `Plan error: ${error instanceof Error ? error.message : String(error)}. No session started.`;
    el.dataset.ok = "false";
    return; // a malformed or unsupported plan starts no session
  }
  const el = byId("plan-status");
  el.textContent = `Plan source: ${loaded.source} · ${describePlan(loaded.plan)}`;
  el.dataset.ok = "true";

  const session = startSession(loaded.plan);
  renderState(session.current(), loaded.plan);
  show("result", "Fresh session at the public start");
  wireTreasure(session);
  wireRange(loaded.plan);
}

void main();
